package com.mediastris.careers;
import java.io.*;
import java.util.zip.*;
import org.apache.poi.poifs.filesystem.POIFSFileSystem;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockMultipartFile;
import static org.assertj.core.api.Assertions.*;
class ResumeFormatsTest {
    @Test void executableWordFieldsAreRejected()throws Exception{byte[] source=docx(false);try(var input=new ZipInputStream(new ByteArrayInputStream(source));var out=new ByteArrayOutputStream();var zip=new ZipOutputStream(out)){for(ZipEntry entry;(entry=input.getNextEntry())!=null;){byte[] content=input.readAllBytes();if(entry.getName().equals("word/document.xml"))content=new String(content,java.nio.charset.StandardCharsets.UTF_8).replace("<w:p/>","<w:p><w:instrText>DDE</w:instrText><w:instrText>AUTO cmd /c calc</w:instrText></w:p>").getBytes(java.nio.charset.StandardCharsets.UTF_8);zip.putNextEntry(new ZipEntry(entry.getName()));zip.write(content);zip.closeEntry();}zip.finish();byte[] bad=out.toByteArray();assertThatThrownBy(()->new ResumeValidator().validate(new MockMultipartFile("resume","resume.docx","application/octet-stream",bad))).isInstanceOf(com.mediastris.contact.ApiException.class);}}
    static byte[] docx(boolean unsafe)throws Exception{try(var output=new ByteArrayOutputStream();var zip=new ZipOutputStream(output)){for(var entry:java.util.Map.of("[Content_Types].xml","<Types xmlns='http://schemas.openxmlformats.org/package/2006/content-types'><Override PartName='/word/document.xml' ContentType='application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml'/></Types>","word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p/></w:body></w:document>","_rels/.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument' Target='word/document.xml'/></Relationships>").entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();}if(unsafe){zip.putNextEntry(new ZipEntry("word/vbaProject.bin"));zip.write("unsafe".getBytes());zip.closeEntry();}zip.finish();return output.toByteArray();}}
    static byte[] doc(boolean macro)throws Exception{try(var filesystem=new POIFSFileSystem();var out=new ByteArrayOutputStream()){byte[] word=new byte[4096];word[0]=(byte)0xec;word[1]=(byte)0xa5;filesystem.getRoot().createDocument("WordDocument",new ByteArrayInputStream(word));filesystem.getRoot().createDocument("0Table",new ByteArrayInputStream(new byte[64]));if(macro)filesystem.getRoot().createDirectory("Macros");filesystem.writeFilesystem(out);return out.toByteArray();}}
    @Test void validWordContainersAreAccepted()throws Exception{var validator=new ResumeValidator();assertThat(validator.validate(new MockMultipartFile("resume","resume.docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document",docx(false))).filename()).isEqualTo("resume.docx");assertThat(validator.validate(new MockMultipartFile("resume","resume.doc","application/msword",doc(false))).filename()).isEqualTo("resume.doc");}
    @Test void macrosAndInvalidContainersAreRejected()throws Exception{for(var file:java.util.List.of(new MockMultipartFile("resume","resume.docx","application/octet-stream",docx(true)),new MockMultipartFile("resume","resume.doc","application/msword",doc(true)),new MockMultipartFile("resume","resume.docx","application/octet-stream","PKfake".getBytes())))assertThatThrownBy(()->new ResumeValidator().validate(file)).isInstanceOf(com.mediastris.contact.ApiException.class);}
    @Test void remotePdfActionsAreRejected()throws Exception{try(var pdf=new org.apache.pdfbox.pdmodel.PDDocument();var output=new ByteArrayOutputStream()){pdf.addPage(new org.apache.pdfbox.pdmodel.PDPage());var action=new org.apache.pdfbox.cos.COSDictionary();action.setName(org.apache.pdfbox.cos.COSName.S,"Launch");action.setString(org.apache.pdfbox.cos.COSName.F,"unsafe.exe");pdf.getDocumentCatalog().getCOSObject().setItem(org.apache.pdfbox.cos.COSName.getPDFName("CustomAction"),action);pdf.save(output);assertThatThrownBy(()->new ResumeValidator().validate(new MockMultipartFile("resume","resume.pdf","application/pdf",output.toByteArray()))).isInstanceOf(com.mediastris.contact.ApiException.class);}}
}
